    public void testReciprocal_Infinite() {
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex result = c.reciprocal();
        assertEquals("Reciprocal of infinite should be ZERO", Complex.ZERO, result);

