import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen4Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testReciprocal_RealGreaterThanImaginary() {
        // Path: FastMath.abs(real) >= FastMath.abs(imaginary)
        // q = imag/real; scale = 1 / (imag * q + real); return (scale, -scale * q)
        Complex c = new Complex(4.0, 2.0);
        Complex result = c.reciprocal();

        // Expected: 1/(4+2i) = (4-2i)/(16+4) = (4/20, -2/20) = (0.2, -0.1)
        assertEquals(0.2, result.getReal(), EPSILON);
        assertEquals(-0.1, result.getImaginary(), EPSILON);
    }






}

