import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen4Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testReciprocal_ImaginaryGreaterThanReal() {
        // Path: FastMath.abs(real) < FastMath.abs(imaginary)
        // q = real/imag; scale = 1 / (real * q + imag); return (scale * q, -scale)
        Complex c = new Complex(2.0, 4.0);
        Complex result = c.reciprocal();

        // Expected: 1/(2+4i) = (2-4i)/(4+16) = (2/20, -4/20) = (0.1, -0.2)
        assertEquals(0.1, result.getReal(), EPSILON);
        assertEquals(-0.2, result.getImaginary(), EPSILON);
    }




}

