import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen4Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testReciprocal_EqualAbs() {
        // Test the boundary condition where abs(real) == abs(imaginary)
        Complex c = new Complex(3.0, 3.0);
        Complex result = c.reciprocal();

        // Expected: 1/(3+3i) = (3-3i)/(9+9) = (3/18, -3/18) = (1/6, -1/6)
        assertEquals(1.0/6.0, result.getReal(), EPSILON);
        assertEquals(-1.0/6.0, result.getImaginary(), EPSILON);
    }
}
